// Unique ID generator for Maelstrom.
//
// Each node in the cluster owns a private, deterministic namespace derived from
// the node ID it is given in the "init" message, plus a monotonically
// increasing local counter. Because node IDs are unique within a cluster and
// counters never repeat inside a node, the pair (node ID, counter) is unique
// across the whole cluster for the whole run.
//
// Crucially, IDs are minted locally: no node ever needs to talk to another
// node to hand out an ID, so requests are answered even while the network is
// partitioned.
package main

import (
	"fmt"
	"io"
	"log"
	"os"
	"strconv"
	"sync"
	"sync/atomic"

	maelstrom "github.com/jepsen-io/maelstrom/demo/go"
)

// limitedWriter keeps the log output bounded: the Maelstrom library logs every
// single message it sends and receives, which would otherwise produce tens of
// thousands of lines per run. We keep the first few lines (useful for
// debugging) and then only emit an occasional progress note.
type limitedWriter struct {
	mu      sync.Mutex
	w       io.Writer
	lines   int
	keep    int
	dropped int
}

func newLimitedWriter(w io.Writer, keep int) *limitedWriter {
	return &limitedWriter{w: w, keep: keep}
}

func (l *limitedWriter) Write(p []byte) (int, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.lines++
	if l.lines <= l.keep {
		return l.w.Write(p)
	}
	l.dropped++
	if l.dropped%20000 == 0 {
		fmt.Fprintf(l.w, "[node] %d log lines suppressed\n", l.lines)
	}
	return len(p), nil
}

func main() {
	// Keep stderr useful but bounded.
	log.SetOutput(newLimitedWriter(os.Stderr, 50))
	errLog := log.New(os.Stderr, "ERROR: ", log.LstdFlags)

	node := maelstrom.NewNode()

	// Closed once the "init" message has been processed. It establishes a
	// happens-before edge between the node ID assignment and every ID we
	// mint, so we never have to guess whether the namespace is ready.
	initialized := make(chan struct{})

	// Counter of IDs minted by this node. Never reset, never reused.
	var counter atomic.Uint64

	// The library handles "init" itself (replying with init_ok) and then
	// delegates to this handler, at which point node.ID() is set.
	node.Handle("init", func(msg maelstrom.Message) error {
		close(initialized)
		return nil
	})

	node.Handle("generate", func(msg maelstrom.Message) error {
		// Wait until we know our own ID (i.e. the init message arrived).
		<-initialized

		// Unique namespace for this node + a never-repeating counter.
		n := counter.Add(1)
		id := node.ID() + "-" + strconv.FormatUint(n, 10)

		return node.Reply(msg, map[string]any{
			"type": "generate_ok",
			"id":   id,
		})
	})

	if err := node.Run(); err != nil {
		errLog.Printf("node stopped: %s", err)
		os.Exit(1)
	}
}

